//!
//! # Public API
//!
//! - `Cache<K, V>`: A thread-safe LRU cache with TTL.
//!   - `new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self`
//!   - `get(&self, key: &K) -> Option<V>`
//!   - `insert(&self, key: K, value: V)`
//!   - `remove(&self, key: &K) -> Option<V>`
//!   - `len(&self) -> usize`
//!   - `clear(&self)`
//!
//! - `Clock`: Trait for injectable time source.
//!   - `now(&self) -> Instant`
//!
//! - `SystemClock`: Default clock using `std::time::Instant`.
//!
//! - `TestClock`: Deterministic clock for tests.
//!   - `new() -> Self`
//!   - `advance(&self, duration: Duration)`
//!   - `set(&self, instant: Instant)`
//!
//! # Ownership Choices
//!
//! - `Arc<Mutex<...>>` wraps the internal state for safe shared access across threads.
//! - Keys and values are owned by the cache; `get` returns a clone of the value.
//! - The clock is shared via `Arc<dyn Clock>` to allow deterministic testing.
//! - LRU order is maintained via a `VecDeque` of keys; access order is updated on `get` and `insert`.
//! - TTL is stored per-entry as an `Instant` deadline; expired entries are lazily removed on access.
//!
//! # Edge Cases Handled
//!
//! - Zero capacity: `insert` is a no-op, `get` always returns `None`, `len` is 0.
//! - Negative capacity is not representable (`usize`), so zero is the minimum.
//! - Repeated `clear` is safe.
//! - Concurrent access is serialized by the mutex.
//! - Expired entries are removed on `get` and `insert` (lazy eviction).
//! - Eviction removes the least recently used entry when capacity is exceeded.

use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for an injectable clock, enabling deterministic tests.
pub trait Clock: Send + Sync {
    /// Returns the current instant.
    fn now(&self) -> Instant;
}

/// Default clock using `std::time::Instant`.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// Deterministic clock for tests.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    /// Creates a new test clock starting at `Instant::now()`.
    pub fn new() -> Self {
        TestClock {
            inner: Mutex::new(Instant::now()),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
