// Task represents a unit of work to be executed by the worker pool.
// The task receives a context that is canceled when the pool is shutting down
// or when the task's deadline expires.
type Task func(ctx context.Context) (interface{}, error)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive. Zero or negative capacity returns an error.
//   - Submit(ctx context.Context, task Task) (<-chan Result, error): Submits a task
//     to the pool. Returns a channel that will receive exactly one Result.
//     If the pool is full, Submit blocks until a worker is available or ctx is canceled.
//     If the pool is closed, Submit returns an error.
//   - Shutdown(ctx context.Context) error: Gracefully shuts down the pool.
//     No new tasks are accepted. Existing tasks complete or are canceled.
//     Returns an error if ctx is canceled before all workers finish.
//   - Close(): Immediately closes the pool, canceling all pending and running tasks.
//     Safe to call multiple times.
//
// Concurrency invariants:
//   - At most `capacity` tasks run concurrently.
//   - Each submitted task produces exactly one Result on its result channel.
//   - Panics in tasks are recovered and delivered as errors in Result.
//   - No goroutine leaks: all worker goroutines exit after Shutdown/Close.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity   int
	tasks      chan taskEnvelope
	workers    sync.WaitGroup
	closed     atomic.Bool
	closeOnce  sync.Once
	shutdownCh chan struct{}
	mu         sync.Mutex
}

type taskEnvelope struct {
	task   Task
	result chan Result
	ctx    context.Context
}

// NewPool creates a new worker pool with the given capacity.
// Capacity must be positive. Returns an error if capacity <= 0.
func NewPool(capacity int) (*Pool, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("workerpool: capacity must be positive, got %d", capacity)
	}
	p := &Pool{
		capacity:   capacity,
		tasks:      make(chan taskEnvelope, capacity),
		shutdownCh: make(chan struct{}),
	}
	// Start workers
	for i := 0; i < capacity; i++ {
		p.workers.Add(1)
		go p.worker()
	}
	return p, nil
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.workers.Done()
	for {
		select {
		case <-p.shutdownCh:
			// Drain remaining tasks with cancellation
			p.drainTasks()
			return
		case envelope, ok := <-p.tasks:
			if !ok {
				// Channel closed, exit
				return
			}
			p.executeTask(envelope)
		}
	}
}

// drainTasks processes any remaining tasks in the queue with canceled contexts.
func (p *Pool) drainTasks() {
	for {
		select {
		case envelope, ok := <-p.tasks:
			if !ok {
				return
			}
			// Deliver a canceled result
			envelope.result <- Result{Err: context.Canceled}
		default:
			return
		}
	}
}

// executeTask runs a single task with panic recovery.
func (p *Pool) executeTask(envelope taskEnvelope) {
	defer func() {
		if r := recover(); r != nil {
			envelope.result <- Result{Err: fmt.Errorf("panic in task: %v", r)}
		}
	}()

