	value, err := envelope.task(envelope.ctx)
	envelope.result <- Result{Value: value, Err: err}
}

// Submit submits a task to the pool. Returns a channel that will receive exactly
// one Result. If the pool is full, Submit blocks until a worker is available or
// ctx is canceled. If the pool is closed, Submit returns an error.
func (p *Pool) Submit(ctx context.Context, task Task) (<-chan Result, error) {
	if p.closed.Load() {
		return nil, errors.New("workerpool: pool is closed")
	}

	resultCh := make(chan Result, 1)
	envelope := taskEnvelope{
		task:   task,
		result: resultCh,
		ctx:    ctx,
	}

	select {
	case p.tasks <- envelope:
		return resultCh, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-p.shutdownCh:
		return nil, errors.New("workerpool: pool is shutting down")
	}
}

// Shutdown gracefully shuts down the pool. No new tasks are accepted.
// Existing tasks complete or are canceled. Returns an error if ctx is canceled
// before all workers finish.
func (p *Pool) Shutdown(ctx context.Context) error {
