// ErrContextCanceled is returned when the context is canceled during submission
// or waiting.
var ErrContextCanceled = errors.New("workerpool: context canceled")

// task represents a unit of work to be executed by a worker.
type task struct {
	fn     func() (interface{}, error)
	result chan<- taskResult
}

// taskResult holds the outcome of a task execution.
type taskResult struct {
	value interface{}
	err   error
}

// Pool is a bounded worker pool.
type Pool struct {
	capacity int
	workers  int

	// queue is the channel of pending tasks.
	queue chan task

	// wg tracks active workers and in-flight tasks for graceful shutdown.
	wg sync.WaitGroup

	// closeOnce ensures Close is idempotent.
	closeOnce sync.Once

	// closed indicates whether the pool has been closed.
	closed bool
	closedMu sync.Mutex

	// pending tracks the number of tasks submitted but not yet completed.
	// Used for Wait().
	pendingMu sync.Mutex
	pending   int
	pendingCond *sync.Cond

	// shutdownDone is closed when all workers have exited.
	shutdownDone chan struct{}
}

// NewPool creates a new worker pool with the given queue capacity and number
// of workers. capacity must be >= 0, workers must be >= 1.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		capacity = 0
	}
	if workers < 1 {
		workers = 1
	}

	p := &Pool{
		capacity:     capacity,
		workers:      workers,
		queue:        make(chan task, capacity),
		shutdownDone: make(chan struct{}),
	}
	p.pendingCond = sync.NewCond(&p.pendingMu)

	// Start workers.
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p
}

// worker is the main loop for a single worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()

	for t := range p.queue {
		p.executeTask(t)
	}
}

// executeTask runs a single task with panic recovery.
func (p *Pool) executeTask(t task) {
	defer func() {
		if r := recover(); r != nil {
