/// uses `std::time::Instant::now()`.
///
/// # Edge Cases
/// - Capacity of 0: `insert` is a no-op, `get` always returns `None`, `len` is 0.
/// - Negative capacity is not representable in `usize`; capacity 0 is the minimum.
/// - TTL of 0: entries expire immediately upon insertion (next `get` returns `None`).
/// - Repeated `remove` of non-existent keys returns `None`.
/// - Concurrent access is safe via `Mutex`; no unsafe code is used.

/// Trait for a clock that can be injected for deterministic testing.
pub trait Clock: Send + Sync {
    /// Returns the current time as an `Instant`.
    fn now(&self) -> Instant;
}

/// Default clock implementation using `std::time::Instant`.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A mock clock for deterministic testing.
pub struct MockClock {
    inner: Mutex<Instant>,
}

impl MockClock {
    /// Creates a new `MockClock` starting at the given instant.
    pub fn new(start: Instant) -> Self {
        MockClock {
            inner: Mutex::new(start),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for MockClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

/// Internal entry stored in the cache.
struct Entry<V> {
    value: V,
    expires_at: Instant,
}

/// Internal state of the LRU cache.
struct CacheState<K, V> {
    /// Map from key to (entry, position in LRU list).
    map: HashMap<K, (Entry<V>, usize)>,
    /// LRU list: front is most recently used, back is least recently used.
    lru: Vec<K>,
    /// Maximum number of entries.
    capacity: usize,
    /// TTL for each entry.
    ttl: Duration,
    /// Clock for time-based expiry.
    clock: Arc<dyn Clock>,
}

impl<K, V> CacheState<K, V>
where
    K: Clone + Eq + std::hash::Hash,
    V: Clone,
{
    fn new(capacity: usize, ttl: Duration, clock: Arc<dyn Clock>) -> Self {
        CacheState {
            map: HashMap::new(),
            lru: Vec::new(),
            capacity,
            ttl,
            clock,
        }
    }

    /// Removes an entry from the LRU list by key.
    fn remove_from_lru(&mut self, key: &K) {
        if let Some(pos) = self.lru.iter().position(|k| k == key) {
            self.lru.remove(pos);
        }
    }

    /// Moves a key to the front of the LRU list (most recently used).
    fn touch(&mut self, key: &K) {
        self.remove_from_lru(key);
        self.lru.insert(0, key.clone());
    }

    /// Evicts the least recently used entry if capacity is exceeded.
    fn evict_if_needed(&mut self) {
        while self.map.len() > self.capacity {
            if let Some(lru_key) = self.lru.pop() {
                self.map.remove(&lru_key);
            } else {
                break;
            }
        }
    }

    /// Checks if an entry has expired.
    fn is_expired(&self, entry: &Entry<V>) -> bool {
        self.clock.now() >= entry.expires_at
    }

    /// Gets a value by key, returning `None` if not found or expired.
    fn get(&mut self, key: &K) -> Option<V> {
        if let Some((entry, _)) = self.map.get(key) {
            if self.is_expired(entry) {
                // Remove expired entry
                self.map.remove(key);
                self.remove_from_lru(key);
                return None;
            }
            let value = entry.value.clone();
            self.touch(key);
            Some(value)
        } else {
            None
        }
    }

    /// Inserts a key-value pair. If the key exists, it is updated and moved to front.
    /// If capacity is exceeded, the LRU entry is evicted.
    fn insert(&mut self, key: K, value: V) {
        if self.capacity == 0 {
            return;
        }

        let now = self.clock.now();
        let expires_at = now + self.ttl;
        let entry = Entry {
            value,
            expires_at,
        };

        if self.map.contains_key(&key) {
            // Update existing entry
            self.map.insert(key.clone(), (entry, 0));
            self.touch(&key);
        } else {
            // Insert new entry
            self.map.insert(key.clone(), (entry, 0));
            self.lru.insert(0, key.clone());
            self.evict_if_needed();
        }
    }

    /// Removes a key from the cache, returning the value if it existed.
    fn remove(&mut self, key: &K) -> Option<V> {
        if let Some((entry, _)) = self.map.remove(key) {
            self.remove_from_lru(key);
            Some(entry.value)
        } else {
            None
        }
    }

    /// Returns the number of entries in the cache.
    fn len(&self) -> usize {
        self.map.len()
    }
}

