package workerpool

import (
	"context"
	"fmt"
	"runtime"
	"sync"
)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// PanicError wraps a panic value and its stack trace.
type PanicError struct {
	Value interface{}
	Stack []byte
}

func (e *PanicError) Error() string {
	return fmt.Sprintf("panic: %v", e.Value)
}

// task represents a unit of work to be executed by a worker.
type task struct {
	fn     func()
	result chan<- Result
}

// Pool is a bounded worker pool.
type Pool struct {
	queue    chan task
	workers  int
	capacity int

	mu       sync.Mutex
	closed   bool
	shutdown bool
	wg       sync.WaitGroup
}

// NewPool creates a new worker pool with the given queue capacity and number
// of workers. capacity must be >= 0; workers must be >= 1.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		capacity = 0
	}
	if workers < 1 {
		workers = 1
	}

	p := &Pool{
		queue:    make(chan task, capacity),
		workers:  workers,
		capacity: capacity,
	}

	// Start workers
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()

	for t := range p.queue {
		p.executeTask(t)
	}
}

// executeTask runs a task with panic recovery.
func (p *Pool) executeTask(t task) {
	defer func() {
		if r := recover(); r != nil {
			stack := make([]byte, 4096)
			n := runtime.Stack(stack, false)
			stack = stack[:n]
			if t.result != nil {
				t.result <- Result{
					Err: &PanicError{Value: r, Stack: stack},
				}
			}
		}
	}()

	if t.fn != nil {
		t.fn()
	}

	if t.result != nil {
		t.result <- Result{}
	}
}

// Submit submits a task to the pool. Blocks if the queue is full (backpressure).
// Returns an error if the pool is closed, the context is canceled, or the
// queue is full and the context is canceled while waiting.
func (p *Pool) Submit(ctx context.Context, fn func()) error {
	if fn == nil {
		return fmt.Errorf("task function is nil")
	}

	p.mu.Lock()
	if p.closed || p.shutdown {
		p.mu.Unlock()
		return fmt.Errorf("pool is closed or shutting down")
	}
	p.mu.Unlock()

	t := task{fn: fn}

	select {
	case p.queue <- t:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// SubmitWithResult submits a task that returns a result. The result is
// delivered on the returned channel. The channel is closed after the result
// is sent. Returns an error if the pool is closed, the context is canceled,
// or the queue is full and the context is canceled while waiting.
func (p *Pool) SubmitWithResult(ctx context.Context, fn func() (interface{}, error)) (<-chan Result, error) {
	if fn == nil {
		return nil, fmt.Errorf("task function is nil")
	}

	p.mu.Lock()
	if p.closed || p.shutdown {
		p.mu.Unlock()
		return nil, fmt.Errorf("pool is closed or shutting down")
	}
	p.mu.Unlock()

	resultCh := make(chan Result, 1)

	t := task{
		fn: func() {
			val, err := fn()
			resultCh <- Result{Value: val, Err: err}
		},
		result: resultCh,
	}

	select {
	case p.queue <- t:
		return resultCh, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	}
