//! - `SystemClock` implements `Clock` using `std::time::Instant`
//! - `TestClock` implements `Clock` for deterministic tests
//!
//! Concurrency: All public methods acquire a single `Mutex` guarding the internal
//! state. This ensures atomicity of get/insert/remove operations and prevents
//! data races. `Arc` is used to share the cache across threads.
//!
//! Ownership: Keys and values are owned by the cache. `get` returns a clone of
//! the value (requiring `V: Clone`). This avoids lifetime complexities and
//! ensures the caller owns the returned data. The cache itself is wrapped in
//! `Arc` for shared ownership across threads.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

/// Trait for a clock that can be injected for testing.
pub trait Clock: Send + Sync {
    /// Returns the current time.
    fn now(&self) -> Instant;
}

/// A clock that uses the system time.
pub struct SystemClock;

impl Clock for SystemClock {
    fn now(&self) -> Instant {
        Instant::now()
    }
}

/// A test clock that allows manual control of time.
pub struct TestClock {
    inner: Mutex<Instant>,
}

impl TestClock {
    /// Creates a new test clock starting at the given instant.
    pub fn new(start: Instant) -> Self {
        TestClock {
            inner: Mutex::new(start),
        }
    }

    /// Advances the clock by the given duration.
    pub fn advance(&self, duration: Duration) {
        let mut guard = self.inner.lock().unwrap();
        *guard += duration;
    }
}

impl Clock for TestClock {
    fn now(&self) -> Instant {
        let guard = self.inner.lock().unwrap();
        *guard
    }
}

