//
//   // Number of tasks waiting to be started (pending).
//   get pendingCount(): number
//
//   // Whether the queue is closed (no new tasks accepted).
//   get isClosed(): boolean
// }
//
// AsyncWorkQueueOptions<T, R>:
//   concurrency: number          // max concurrent running tasks (>= 1)
//   capacity: number             // max pending + running tasks (>= 0)
//   taskExecutor: (task: T, signal: AbortSignal) => Promise<R>
//   onError?: (error: unknown, task: T) => void  // optional error handler
//
// ============================================================================

// ---------------------------------------------------------------------------
// Type Definitions
// ---------------------------------------------------------------------------

interface AsyncWorkQueueOptions<T, R> {
  concurrency: number;
  capacity: number;
  taskExecutor: (task: T, signal: AbortSignal) => Promise<R>;
  onError?: (error: unknown, task: T) => void;
}

interface QueuedTask<T, R> {
  task: T;
  resolve: (value: R) => void;
  reject: (reason: unknown) => void;
  abortController: AbortController;
  status: 'pending' | 'running' | 'completed' | 'cancelled';
  started: boolean;
}

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

class AsyncWorkQueue<T, R> {
  private readonly concurrency: number;
  private readonly capacity: number;
  private readonly taskExecutor: (task: T, signal: AbortSignal) => Promise<R>;
  private readonly onError?: (error: unknown, task: T) => void;

  private pendingQueue: QueuedTask<T, R>[] = [];
  private runningTasks: Set<QueuedTask<T, R>> = new Set();
  private closed: boolean = false;
  private draining: boolean = false;
  private drainResolvers: Array<() => void> = [];

  // Track total tasks that have been enqueued but not yet fully resolved/rejected
  // to help with drain logic.
  private activeTaskCount: number = 0;

  constructor(options: AsyncWorkQueueOptions<T, R>) {
    if (options.concurrency < 1) {
      throw new Error('concurrency must be >= 1');
    }
    if (options.capacity < 0) {
      throw new Error('capacity must be >= 0');
    }
    if (typeof options.taskExecutor !== 'function') {
      throw new Error('taskExecutor must be a function');
    }

    this.concurrency = options.concurrency;
    this.capacity = options.capacity;
    this.taskExecutor = options.taskExecutor;
    this.onError = options.onError;
  }

  get runningCount(): number {
    return this.runningTasks.size;
  }

  get pendingCount(): number {
    return this.pendingQueue.length;
  }

  get isClosed(): boolean {
    return this.closed;
  }

