// Task represents a unit of work to be executed by the worker pool.
// The function receives a context that is canceled when the pool is shutting down
// or when the task's deadline/context is canceled.
type Task func(ctx context.Context) (interface{}, error)

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int) *Pool: Creates a new pool with the given worker capacity.
//     Capacity must be positive. Zero or negative capacity returns an error.
//   - Submit(ctx context.Context, task Task) error: Submits a task to the pool.
//     Returns an error if the pool is closed, the context is canceled, or the
//     submission queue is full (backpressure). Blocks if the queue is full until
//     space becomes available or the context is canceled.
//   - Shutdown(ctx context.Context) error: Initiates graceful shutdown. No new tasks
//     can be submitted. Existing tasks complete. Returns an error if the context
//     is canceled before all tasks complete.
//   - Wait(): Blocks until all submitted tasks have completed and the pool is shut down.
//     Safe to call multiple times.
//
// Concurrency invariants:
//   - At most `capacity` tasks execute concurrently.
//   - Tasks are executed in FIFO order relative to submission.
//   - Panics in tasks are recovered and converted to errors in Result.
//   - No goroutine leaks: all worker goroutines exit after Shutdown completes.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity   int
	taskQueue  chan Task
	resultChan chan Result
	workerWg   sync.WaitGroup
	closeOnce  sync.Once
	closed     atomic.Bool
	shutdownWg sync.WaitGroup
	mu         sync.Mutex
	pending    int
}

// NewPool creates a new worker pool with the given capacity.
// Capacity must be positive. Returns an error if capacity <= 0.
func NewPool(capacity int) (*Pool, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("capacity must be positive, got %d", capacity)
	}
	p := &Pool{
		capacity:  capacity,
		taskQueue: make(chan Task, capacity),
	}
