// Package workerpool provides a bounded worker pool with context cancellation,
// task submission with backpressure, panic recovery, graceful shutdown, and
// deterministic result delivery.
//
// Public API:
//
//   - NewPool(capacity int, workers int) *Pool
//     Creates a new pool with the given queue capacity and number of workers.
//     capacity must be >= 0; workers must be >= 1.
//
//   - (*Pool).Submit(ctx context.Context, task func() (interface{}, error)) error
//     Submits a task to the pool. Blocks if the queue is full (backpressure).
//     Returns an error if the context is canceled, the pool is closed, or the
//     queue is full and the context is canceled while waiting.
//
//   - (*Pool).Close()
//     Initiates graceful shutdown. No new tasks can be submitted after Close
//     is called. Existing tasks in the queue will be processed. Close blocks
//     until all workers have finished processing their current tasks and the
//     queue is empty.
//
//   - (*Pool).Wait()
//     Blocks until all submitted tasks have completed (including those that
//     were rejected due to cancellation or pool closure).
//
// Concurrency invariants:
//   - The number of concurrently executing tasks never exceeds the number of
//     workers.
//   - The number of queued tasks never exceeds the capacity.
//   - All tasks submitted before Close are either executed or their results
//     are delivered via the task's completion mechanism.
//   - Panics in tasks are recovered and converted to errors.
//   - No goroutine leaks: all worker goroutines exit after Close.
//   - No data races: all shared state is protected by mutexes or channels.
package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
)

// ErrPoolClosed is returned when attempting to submit to a closed pool.
var ErrPoolClosed = errors.New("workerpool: pool is closed")

// ErrQueueFull is returned when the queue is full and the context is canceled
// while waiting for space.
var ErrQueueFull = errors.New("workerpool: queue is full")

// ErrContextCanceled is returned when the context is canceled before the task
// can be submitted.
var ErrContextCanceled = errors.New("workerpool: context canceled")

// task represents a unit of work to be executed by a worker.
type task struct {
	fn     func() (interface{}, error)
	result chan<- taskResult
}

// taskResult holds the outcome of a task execution.
type taskResult struct {
	value interface{}
	err   error
}

// Pool is a bounded worker pool.
type Pool struct {
	capacity int
	workers  int

	queue chan task

	// mu protects the closed flag and the wait group.
	mu     sync.Mutex
	closed bool

	// wg tracks all submitted tasks (including those that may be rejected).
	wg sync.WaitGroup

	// workerWg tracks worker goroutines.
	workerWg sync.WaitGroup

	// closeOnce ensures Close is idempotent.
	closeOnce sync.Once
}

// NewPool creates a new worker pool with the given queue capacity and number
// of workers. capacity must be >= 0; workers must be >= 1.
// If capacity is 0, the queue is unbuffered, meaning Submit will block until
// a worker is ready to accept the task.
func NewPool(capacity int, workers int) *Pool {
	if capacity < 0 {
		panic("workerpool: capacity must be >= 0")
	}
	if workers < 1 {
		panic("workerpool: workers must be >= 1")
	}

	p := &Pool{
		capacity: capacity,
		workers:  workers,
		queue:    make(chan task, capacity),
	}

	// Start worker goroutines.
	p.workerWg.Add(workers)
	for i := 0; i < workers; i++ {
		go p.worker()
	}

	return p
}

// worker is the main loop for each worker goroutine.
func (p *Pool) worker() {
	defer p.workerWg.Done()

	for t := range p.queue {
		p.executeTask(t)
	}
}

// executeTask runs the task function, recovering from panics, and sends the
// result to the result channel.
func (p *Pool) executeTask(t task) {
	defer func() {
		if r := recover(); r != nil {
			t.result <- taskResult{
				value: nil,
				err:   fmt.Errorf("panic in task: %v", r),
			}
		}
	}()

	value, err := t.fn()
	t.result <- taskResult{
		value: value,
		err:   err,
	}
}

// Submit submits a task to the pool. It blocks if the queue is full until
// space becomes available or the context is canceled.
// Returns an error if the pool is closed, the context is canceled, or the
// queue is full and the context is canceled while waiting.
func (p *Pool) Submit(ctx context.Context, fn func() (interface{}, error)) error {
	if fn == nil {
		return errors.New("workerpool: task function is nil")
	}

	// Check if the pool is closed before attempting to submit.
	p.mu.Lock()
	if p.closed {
		p.mu.Unlock()
		return ErrPoolClosed
	}
	p.mu.Unlock()

	// Create a result channel for this task.
	resultCh := make(chan taskResult, 1)

	t := task{
		fn:     fn,
		result: resultCh,
	}

	// Increment the wait group to track this task.
	p.wg.Add(1)

