	Execute(ctx context.Context) (interface{}, error)
}

// TaskFunc is a convenience type that adapts a function to the Task interface.
type TaskFunc func(ctx context.Context) (interface{}, error)

// Execute implements the Task interface.
func (f TaskFunc) Execute(ctx context.Context) (interface{}, error) {
	return f(ctx)
}

// Result holds the outcome of a task execution.
type Result struct {
	Value interface{}
	Err   error
}

// ErrPoolClosed is returned when submitting to a closed pool.
var ErrPoolClosed = errors.New("worker pool is closed")

// ErrPoolFull is returned when the pool's queue is full and backpressure is applied.
var ErrPoolFull = errors.New("worker pool queue is full")

// ErrTaskPanic is returned when a task panics during execution.
var ErrTaskPanic = errors.New("task panicked")

// Pool is a bounded worker pool with context cancellation, backpressure,
// panic recovery, graceful shutdown, and deterministic result delivery.
//
// Public API:
//   - NewPool(capacity int, queueSize int) *Pool
//     Creates a new pool with the given number of workers and queue capacity.
//     capacity must be >= 1. queueSize must be >= 0.
//   - Submit(ctx context.Context, task Task) error
//     Submits a task to the pool. Returns ErrPoolClosed if the pool is closed,
//     ErrPoolFull if the queue is full and the context is not canceled.
//     Blocks until space is available or the context is canceled.
//   - Shutdown(ctx context.Context) error
//     Gracefully shuts down the pool. Stops accepting new tasks, waits for
//     in-flight tasks to complete (or context cancellation), and releases resources.
//     Returns ErrPoolClosed if already closed.
//   - Close()
//     Immediately closes the pool, canceling all pending and in-flight tasks.
//     Safe to call multiple times.
//
// Concurrency invariants:
//   - At most `capacity` workers are active at any time.
//   - Tasks are executed in FIFO order from the queue.
//   - Each task's result is delivered exactly once via the Result channel.
//   - Panics in tasks are recovered and converted to errors.
//   - No goroutine leaks: all worker goroutines exit after Close/Shutdown.
//   - No data races: all shared state is protected by mutexes or atomic operations.
type Pool struct {
	capacity  int
	queueSize int

	// queue is a buffered channel of tasks. Its capacity is queueSize.
	queue chan Task

	// results is a buffered channel for delivering results.
	// Each submitted task gets exactly one result delivered here.
	results chan Result

	// workers tracks the number of active worker goroutines.
	workers atomic.Int64

	// closed indicates whether the pool has been closed.
	closed atomic.Bool

	// closeOnce ensures Close/Shutdown logic runs only once.
	closeOnce sync.Once

	// shutdownCtx is the context used to cancel in-flight tasks during shutdown.
	shutdownCtx    context.Context
	shutdownCancel context.CancelFunc

	// mu protects the state transitions and ensures proper ordering.
	mu sync.Mutex

	// wg tracks all worker goroutines for graceful shutdown.
	wg sync.WaitGroup

	// taskCount tracks the number of tasks submitted but not yet completed.
	// Used to ensure all tasks complete before shutdown returns.
	taskCount atomic.Int64

	// taskDone is a channel that signals when a task completes.
	// Used to wait for all tasks during shutdown.
	taskDone chan struct{}
}

// NewPool creates a new worker pool with the specified number of workers and queue size.
// capacity must be >= 1. queueSize must be >= 0.
// If capacity < 1, it defaults to 1. If queueSize < 0, it defaults to 0.
func NewPool(capacity int, queueSize int) *Pool {
	if capacity < 1 {
		capacity = 1
	}
	if queueSize < 0 {
		queueSize = 0
	}

	p := &Pool{
		capacity:  capacity,
		queueSize: queueSize,
		queue:     make(chan Task, queueSize),
		results:   make(chan Result, queueSize+capacity), // enough buffer for all in-flight tasks
		taskDone:  make(chan struct{}, capacity+queueSize+1),
	}
	p.shutdownCtx, p.shutdownCancel = context.WithCancel(context.Background())

	// Start worker goroutines
	for i := 0; i < capacity; i++ {
		p.wg.Add(1)
		go p.worker()
	}

	return p
}

// worker is the main loop for each worker goroutine.
// It reads tasks from the queue, executes them, and delivers results.
func (p *Pool) worker() {
	defer p.wg.Done()
	p.workers.Add(1)
	defer p.workers.Add(-1)

	for {
		// Check if the pool is closed before trying to receive a task.
		if p.closed.Load() {
			return
		}

		// Try to receive a task from the queue.
		// Use a select with shutdownCtx to allow cancellation during shutdown.
		select {
		case <-p.shutdownCtx.Done():
			// Pool is shutting down; drain remaining tasks if possible, then exit.
			// We continue to process queued tasks until the queue is empty.
			for {
				select {
				case task := <-p.queue:
					p.executeTask(task)
				default:
					return
				}
			}
		case task, ok := <-p.queue:
			if !ok {
				// Queue is closed; exit.
				return
			}
			p.executeTask(task)
		}
	}
}

